//! Raw FFI bindings to [libghostty-vt](https://lib.ghostty.org/vt/).
//!
//! `bindings.rs` is generated by bindgen from `ghostty/vt.h`; see
//! `regen-bindings.sh`. Macros that bindgen cannot translate (because
//! they involve casts or are `static inline`) are re-implemented here.
#![no_std]

mod bindings;
pub use bindings::*;

pub const GHOSTTY_STYLE_FLAG_BOLD: GhosttyStyleFlags = 1 << 0;
pub const GHOSTTY_STYLE_FLAG_ITALIC: GhosttyStyleFlags = 1 << 1;
pub const GHOSTTY_STYLE_FLAG_FAINT: GhosttyStyleFlags = 1 << 2;
pub const GHOSTTY_STYLE_FLAG_BLINK: GhosttyStyleFlags = 1 << 3;
pub const GHOSTTY_STYLE_FLAG_INVERSE: GhosttyStyleFlags = 1 << 4;
pub const GHOSTTY_STYLE_FLAG_INVISIBLE: GhosttyStyleFlags = 1 << 5;
pub const GHOSTTY_STYLE_FLAG_STRIKETHROUGH: GhosttyStyleFlags = 1 << 6;
pub const GHOSTTY_STYLE_FLAG_OVERLINE: GhosttyStyleFlags = 1 << 7;
pub const GHOSTTY_STYLE_UNDERLINE_SHIFT: u16 = 8;
pub const GHOSTTY_STYLE_UNDERLINE_MASK: GhosttyStyleFlags = 0x7 << GHOSTTY_STYLE_UNDERLINE_SHIFT;

/// Equivalent of the `GHOSTTY_STYLE_UNDERLINE()` macro.
#[inline]
pub fn ghostty_style_underline(style: &GhosttyStyle) -> GhosttySgrUnderline {
    ((style.flags & GHOSTTY_STYLE_UNDERLINE_MASK) >> GHOSTTY_STYLE_UNDERLINE_SHIFT)
        as GhosttySgrUnderline
}

/// Equivalent of the `static inline ghostty_mode_new()` helper.
#[inline]
pub const fn ghostty_mode_new(value: u16, ansi: bool) -> GhosttyMode {
    (value & 0x7fff) | ((ansi as u16) << 15)
}

